"""TASK 04 · QC_REPORT.md from the Blender QC runs (12_RENDER/qc/qc_blender_*.json) — system python3."""
import os, json, glob

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
runs = [json.load(open(p)) for p in sorted(glob.glob(os.path.join(ROOT, '12_RENDER', 'qc', 'qc_blender_*.json')))]
log = json.load(open(os.path.join(ROOT, '12_RENDER', 'render_log.json')))
L = ['# TASK 04 — TECHNICAL QC REPORT (3D world blockout, milestone 1)', '',
     '> Generated by `scripts/w4_qc.py` (runs inside Blender) + `scripts/w4_qc_report.py`. Status of the geography itself: **PROPOSAL** (map rev 01, not locked).', '']
for r in runs:
    p = sum(c['result'] == 'PASS' for c in r['checks'])
    L += [f"## Blender {r['blender']} — {p} / {len(r['checks'])} PASS", '', '| Check | Result | Detail |', '|---|---|---|']
    for c in r['checks']:
        L.append(f"| {c['check']} | {'✅' if c['result'] == 'PASS' else '❌'} {c['result']} | {c['detail'].replace('|', '/')} |")
    L.append('')
if runs:
    r = runs[0]
    L += ['## Files', '', '| File | Saved with | Scenes | Objects | Meshes | Vertices | Cameras | Linked libraries |', '|---|---|---|---|---|---|---|---|']
    for f, i in r['files'].items():
        L.append(f"| `{f}` | {i['saved_with']} | {', '.join(i['scenes'])} | {i['objects']} | {i['meshes']} | {i['verts']:,} | {i['cameras']} | {len(i['libraries'])} |")
    L.append('')
L += ['## Render log', '', '| Camera | Mode | Seconds | File |', '|---|---|---|---|']
for e in log:
    L.append(f"| {e['camera']} | {e['mode']} | {e['seconds']} | `{e['file']}` |")
L.append('')
open(os.path.join(ROOT, 'QC_REPORT.md'), 'w').write('\n'.join(L))
print('QC_REPORT written', len(runs), 'runs')
